
/* ================= v6 CORE ADDITIONS ================= */
const SCOPES=[['all','Everything','globe'],['projects','Projects & tasks','projects'],['tasks','Tasks','tasks'],['clients','Clients','clients'],['drive','Docs & files','drive'],['office','Office','office'],['planner','Planner','planner'],['fmp','Funnels','fmp']];
function usOpen(q=''){closeCmdk();const here=SCOPES.some(s=>s[0]===RT.a)?RT.a:'all';if(US.keep!==RT.a){US.scope=here;US.keep=RT.a}
const d=document.createElement('div');d.className='cmdk-scrim';d.innerHTML=`<div class="cmdk" role="dialog" aria-label="Search everything"><div class="cmdk-in">${ic('search',20)}<input id="usq" placeholder="Search ${US.scope==='all'?'everything you can open':SCOPES.find(s=>s[0]===US.scope)[1]}" value="${esc(q)}" autocomplete="off"><kbd>Esc</kbd></div>
<div class="cmdk-scope"><span class="over">Search in</span><div class="cmdk-chips" role="radiogroup" aria-label="Where to search">${SCOPES.map(([k,l,i])=>`<button role="radio" aria-checked="${US.scope===k}" aria-pressed="${US.scope===k}" data-act="usscope:${k}">${k==='all'?ic('globe',14):plate(app(i),16)}${l}</button>`).join('')}</div></div>
<div class="cmdk-res" id="usr"></div><div class="cmdk-foot"><span><kbd>↑</kbd><kbd>↓</kbd> move</span><span><kbd>Enter</kbd> open</span><span><kbd>Ctrl</kbd>+<kbd>Enter</kbd> new tab</span><span><kbd>Tab</kbd> next scope</span><span class="grow"></span><button class="linkbtn" style="min-height:0;font-size:12.5px" data-act="ushelp">How search works</button></div></div>`;document.body.append(d);usRun();setTimeout(()=>$('#usq').focus(),20)}
ACT.ushelp=()=>dlg({title:'How search works',body:`<ul class="ticks" style="margin-top:10px"><li>${ic('check',16,'',2.6)}It searches every app you can open in ${oname()}. Nothing from the other organization, and nothing you aren’t allowed to see.</li><li>${ic('check',16,'',2.6)}Pick a scope chip, or type <kbd>in:clients</kbd>, <kbd>in:projects</kbd>, <kbd>in:drive</kbd>.</li><li>${ic('check',16,'',2.6)}Filters: <kbd>@me</kbd> assigned to me · <kbd>overdue</kbd> · <kbd>is:archived</kbd> archived projects.</li><li>${ic('check',16,'',2.6)}Small typos are forgiven. Results show which app they come from.</li><li>${ic('check',16,'',2.6)}Inside an app, its own search box filters only the page you’re on.</li></ul>`,acts:[['Got it','noop','primary']]});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&e.target.id==='usq'){e.preventDefault();const i=SCOPES.findIndex(s=>s[0]===US.scope);ACT.usscope(SCOPES[(i+(e.shiftKey?-1:1)+SCOPES.length)%SCOPES.length][0])}},true);
INPUT.usq=e=>{const m=e.value.match(/in:(\w+)/);if(m){const map={projects:'projects',tasks:'tasks',clients:'clients',drive:'drive',files:'drive',docs:'drive',office:'office',planner:'planner',funnels:'fmp',fmp:'fmp'};if(map[m[1]]){e.value=e.value.replace(m[0],'').trim();ACT.usscope(map[m[1]])}}usRun()};
/* ---------- profile page (global, not inside Office) ---------- */
VIEWS.profile=p=>{const t=p[0]||'about';const T=[['about','Profile'],['account','Account & sign-in'],['notifications','Notifications'],['appearance','Appearance']];
return `<div class="shell" data-app="profile">${rail('profile')}<div class="main" style="grid-column:2/-1">${focusBar('office',{title:'<b>Your profile</b>',sub:'Shared across every app and both organizations',back:'launcher'}).replace(plate(app('office'),26),photo(26))}
<div class="prof"><div class="prof-head"><div class="prof-cover"></div><div class="prof-row"><button class="prof-photo" data-act="photoedit" aria-label="Change photo">${photo(112)}<span>${ic('imgI',16)}</span></button><div class="grow"><h1 class="h1">Tabish Riaz</h1><p class="tx2">Owner · Layer2Funnels &nbsp;·&nbsp; Owner · Aurj</p></div><a class="btn ghost sm" href="#/office/member/TR">${plate(app('office'),20)}My work in Office</a></div></div>
<nav class="prof-tabs">${T.map(([k,l])=>`<a href="#/profile/${k}" aria-selected="${k===t}">${l}</a>`).join('')}</nav>
${t==='about'?`<div class="split"><section class="panel pad"><div class="row2"><div class="field"><label>Full name</label><input value="Tabish Riaz"></div><div class="field"><label>Display name</label><input value="Tabish"></div></div><div class="row2"><div class="field"><label>Job title</label><input value="Founder"></div><div class="field"><label>Time zone</label><select><option>Asia/Karachi (PKT)</option></select></div></div><div class="field"><label>About</label><textarea>Building funnels for coaches and teaching in Urdu.</textarea></div><button class="btn primary" data-act="toast:Profile saved.:ok">Save</button></section>
<section class="panel pad"><p class="sec-t" style="margin-top:0">Your organizations</p>${Object.keys(ORG).map(o=>`<div class="linkrow" style="min-height:52px">${mark(o,32)}<span class="main"><b>${ORG[o].name}</b><small>Owner · teammate${o==='l2f'?' · also client of 0 clients':''}</small></span></div>`).join('')}<p class="hint">One sign-in. Each organization keeps its own data and your role in it.</p></section></div>`:''}
${t==='account'?`<section class="panel pad" style="max-width:640px"><div class="field"><label>Email</label><input value="tabish@layer2funnels.com" readonly></div><div class="linkrow" style="border:var(--bw) solid var(--line)">${ic('key')}<span class="main"><b>Password</b><small>Changed 3 months ago</small></span><button class="btn ghost sm" data-act="toast:Change password opens.">Change</button></div><div class="linkrow" style="border:var(--bw) solid var(--line);margin-top:8px">${ic('google')}<span class="main"><b>Google sign-in</b><small>Turns on at go-live</small></span><span class="pill">Later</span></div><div class="linkrow" style="border:var(--bw) solid var(--line);margin-top:8px">${ic('desk')}<span class="main"><b>Signed-in devices</b><small>This Chrome on Windows · now</small></span><button class="btn quiet sm" data-act="toast:Signed out of other devices.:ok">Sign out others</button></div></section>`:''}
${t==='notifications'?`<p class="lede" style="margin-bottom:12px">Notifications from every app arrive in one inbox, the bell on the left. Choose what reaches you.</p>${notifSettings()}`:''}
${t==='appearance'?`<section class="panel pad" style="max-width:640px"><p class="sec-t" style="margin-top:0">Theme</p><div class="chiprow">${['light','dark'].map(x=>`<button class="chip" aria-pressed="${H.dataset.theme===x}" data-act="demo:theme=${x}">${ic(x==='light'?'sun':'moon',16)}${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}<button class="chip" aria-pressed="false" data-act="toast:Follows your device.">System</button></div><div class="tg-row">Weather and time sky on the Launcher<button class="toggle" role="switch" aria-checked="${DEMO.wx!=='off'}" data-act="wxtoggle" aria-label="Weather"></button></div><div class="tg-row">Reduce motion<button class="toggle" role="switch" aria-checked="false" data-act="tgl" aria-label="Reduce motion"></button></div><div class="tg-row">Compact density<button class="toggle" role="switch" aria-checked="false" data-act="tgl" aria-label="Compact"></button></div></section>`:''}</div></div></div>`};
